    def test_stable_read_default_is_unchanged_and_allowed_opens_only_the_named_file(self):
        with tempfile.TemporaryDirectory() as folder:
            path = Path(folder) / "OroHermandad.lua"
            path.write_text("OroHermandadHist = {}", encoding="utf-8")
            with self.assertRaises(sync.SyncError) as raised:
                sync.stable_read(path)
            self.assertEqual(str(raised.exception), "Solo se admiten los dos archivos SavedVariables del conector.")
            self.assertEqual(sync.stable_read(path, allowed=h.ALLOWED).text, "OroHermandadHist = {}")
            other = Path(folder) / "Auctionator.lua"
            other.write_text("x = 1", encoding="utf-8")
            with self.assertRaises(sync.SyncError):
                sync.stable_read(other, allowed=h.ALLOWED)


